+type Node = TextNode | ExprNode | BlockNode | CommentNode;
+type TextNode = { kind: 'text'; text: string };
+type ExprNode = { kind: 'expr'; path: string; raw: boolean; line: number; col: number };
+type CommentNode = { kind: 'comment' };
+type BlockNode = { kind: 'if' | 'each'; path: string; yes: Node[]; no: Node[]; line: number; col: number };
+type Frame = { item: unknown; index: number };
+
+const scalar = (v: unknown, line: number, col: number): string => {
+  if (v === null || v === undefined) return '';
+  if (typeof v === 'object' || typeof v === 'function') throw new Error(`Cannot render ${typeof v} as text at line ${line}, column ${col}`);
+  return String(v);
+};
+const escape = (s: string) => s.replace(/[&<>"']/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c]!));
+const truthy = (v: unknown) => !(v === '' || v === 0 || v === false || v === null || v === undefined || (Array.isArray(v) && v.length === 0));
+
+function position(s: string, at: number) { const before = s.slice(0, at); return { line: before.split('\n').length, col: at - before.lastIndexOf('\n') }; }
+function parse(template: string): Node[] {
+  const root: Node[] = [], stack: Array<{ block: BlockNode; parent: Node[]; inElse: boolean }> = [];
+  let current = root, pos = 0;
+  const add = (n: Node) => current.push(n);
+  while (pos < template.length) {
+    const start = template.indexOf('{{', pos);
+    if (start < 0) { add({kind:'text', text:template.slice(pos)}); break; }
+    if (start > pos) add({kind:'text', text:template.slice(pos, start)});
+    const triple = template.startsWith('{{{', start);
+    const end = template.indexOf(triple ? '}}}' : '}}', start + (triple ? 3 : 2));
+    if (end < 0) { const p=position(template,start); throw new Error(`Unclosed tag at line ${p.line}, column ${p.col}`); }
+    const p=position(template,start), body=template.slice(start+(triple?3:2),end).trim(); pos=end+(triple?3:2);
+    if (triple) { if (!body) throw new Error(`Empty interpolation at line ${p.line}, column ${p.col}`); add({kind:'expr',path:body,raw:true,line:p.line,col:p.col}); continue; }
+    if (body.startsWith('!')) { add({kind:'comment'}); continue; }
+    if (body === 'else') { if (!stack.length) throw new Error(`else outside block at line ${p.line}, column ${p.col}`); const top=stack[stack.length-1]; if(top.inElse) throw new Error(`Duplicate else at line ${p.line}, column ${p.col}`); top.inElse=true; current=top.block.no; continue; }
+    if (body.startsWith('#')) { const m=body.match(/^#(if|each)\s+(.+)$/); if(!m) throw new Error(`Unknown block at line ${p.line}, column ${p.col}`); const b:BlockNode={kind:m[1] as 'if'|'each',path:m[2].trim(),yes:[],no:[],line:p.line,col:p.col}; add(b); stack.push({block:b,parent:current,inElse:false}); current=b.yes; continue; }
