+function renderNodes(nodes: Node[], root: unknown, frames: Frame[]): string { let out=''; for(const n of nodes) { if(n.kind==='text'||n.kind==='comment') {out+=n.kind==='text'?n.text:''; continue;} if(n.kind==='expr'){const s=scalar(lookup(n.path,root,frames),n.line,n.col);out+=n.raw?s:escape(s);continue;} const v=lookup(n.path,root,frames); if(n.kind==='if') out+=renderNodes(truthy(v)?n.yes:n.no,root,frames); else if(Array.isArray(v)) out+=v.length? v.map((x,i)=>renderNodes(n.yes,root,frames.concat({item:x,index:i}))).join(''):renderNodes(n.no,root,frames); else if(!truthy(v)) out+=renderNodes(n.no,root,frames); else throw new Error(`each expects an array at line ${n.line}, column ${n.col}`); } return out; }
